[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>CoinTracker Pro — Cryptocurrency Prices, Charts and Market Capitalizations</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet" />
  <style>
    /* ─── Reset & Variables ─────────────────────────────────────────────── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --brand-blue: #3861FB;
      --brand-blue-hover: #2a4edb;
      --brand-navy: #0D1421;
      --brand-gray: #808A9D;
      --bg: #ffffff;
      --bg-secondary: #F8FAFD;
      --bg-tertiary: #EFF2F5;
      --border: #E5E9F0;
      --border-light: #F0F3F9;
      --text-primary: #0D1421;
      --text-secondary: #58667E;
      --text-muted: #808A9D;
      --green: #16C784;
      --red: #EA3943;
      --green-bg: rgba(22, 199, 132, 0.08);
      --red-bg: rgba(234, 57, 67, 0.08);
      --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
      --shadow-md: 0 4px 16px rgba(0,0,0,0.08);
      --radius-sm: 4px;
      --radius: 8px;
      --radius-lg: 12px;
      --font: 'Plus Jakarta Sans', -apple-system, sans-serif;
      --mono: 'JetBrains Mono', 'Courier New', monospace;
      font-size: 14px;
    }

    body {
      font-family: var(--font);
      color: var(--text-primary);
      background: var(--bg);
      line-height: 1.5;
      -webkit-font-smoothing: antialiased;
      overflow-x: hidden;
    }

    a { color: inherit; text-decoration: none; }
    button { cursor: pointer; border: none; background: none; font-family: var(--font); }
    svg { display: block; }

    /* ─── Scrollbar ─────────────────────────────────────────────────────── */
    ::-webkit-scrollbar { width: 6px; height: 6px; }
    ::-webkit-scrollbar-track { background: var(--bg-tertiary); }
    ::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }

    /* ─── Promo Banner ──────────────────────────────────────────────────── */
    .promo-banner {
      background: linear-gradient(90deg, #1a1f3a 0%, #0D1421 100%);
      color: #fff;
      padding: 9px 16px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      font-size: 12.5px;
      font-weight: 500;
      position: relative;
      overflow: hidden;
      min-height: 36px;
    }
    .promo-banner .promo-slides { flex: 1; text-align: center; }
    .promo-slide { display: none; align-items: center; justify-content: center; gap: 8px; }
    .promo-slide.active { display: flex; }
    .promo-badge {
      background: var(--brand-blue);
      color: #fff;
      font-size: 10px;
      font-weight: 700;
      padding: 2px 7px;
      border-radius: 3px;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }
    .promo-cta {
      background: linear-gradient(135deg, #3861FB, #6c8fff);
      color: #fff;
      padding: 5px 14px;
      border-radius: var(--radius-sm);
      font-size: 12px;
      font-weight: 600;
      white-space: nowrap;
      transition: opacity 0.2s;
    }
    .promo-cta:hover { opacity: 0.88; }
    .promo-nav { display: flex; gap: 4px; align-items: center; }
    .promo-dot {
      width: 6px; height: 6px;
      border-radius: 50%;
      background: rgba(255,255,255,0.3);
      cursor: pointer;
      transition: background 0.2s;
    }
    .promo-dot.active { background: #fff; }

    /* ─── Top Nav ────────────────────────────────────────────────────────── */
    .topnav {
      background: var(--bg);
      border-bottom: 1px solid var(--border);
      position: sticky;
      top: 0;
      z-index: 100;
    }
    .topnav-inner {
      max-width: 1440px;
      margin: 0 auto;
      padding: 0 20px;
      display: flex;
      align-items: center;
      gap: 0;
      height: 56px;
    }
    .logo {
      display: flex;
      align-items: center;
      gap: 8px;
      font-weight: 700;
      font-size: 17px;
      color: var(--brand-navy);
      white-space: nowrap;
      margin-right: 28px;
    }
    .logo-icon {
      width: 28px; height: 28px;
      background: var(--brand-blue);
      border-radius: 6px;
      display: flex; align-items: center; justify-content: center;
    }
    .nav-links {
      display: flex;
      align-items: center;
      gap: 0;
      flex: 1;
      height: 100%;
      list-style: none;
    }
    .nav-links li {
      height: 100%;
      display: flex;
      align-items: center;
    }
    .nav-links a {
      padding: 0 14px;
      height: 100%;
      display: flex;
      align-items: center;
      gap: 4px;
      font-size: 13.5px;
      font-weight: 500;
      color: var(--text-secondary);
      white-space: nowrap;
      border-bottom: 2px solid transparent;
      transition: color 0.15s, border-color 0.15s;
    }
    .nav-links a:hover,
    .nav-links a.active {
      color: var(--brand-blue);
      border-bottom-color: var(--brand-blue);
    }
    .nav-chevron {
      width: 12px; height: 12px;
      stroke: currentColor;
      fill: none;
      stroke-width: 2;
    }
    .nav-actions {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-left: auto;
    }
    .btn-login {
      padding: 7px 16px;
      border: 1px solid var(--border);
      border-radius: var(--radius-sm);
      font-size: 13.5px;
      font-weight: 600;
      color: var(--text-primary);
      transition: border-color 0.15s, background 0.15s;
    }
    .btn-login:hover { border-color: var(--brand-blue); color: var(--brand-blue); }
    .btn-signup {
      padding: 7px 16px;
      background: var(--brand-blue);
      border-radius: var(--radius-sm);
      font-size: 13.5px;
      font-weight: 600;
      color: #fff;
      transition: background 0.15s;
    }
    .btn-signup:hover { background: var(--brand-blue-hover); }

    /* ─── Market Stats Bar ──────────────────────────────────────────────── */
    .stats-bar {
      background: var(--bg);
      border-bottom: 1px solid var(--border-light);
      padding: 0;
      overflow-x: auto;
      white-space: nowrap;
    }
    .stats-bar::-webkit-scrollbar { height: 0; }
    .stats-bar-inner {
      max-width: 1440px;
      margin: 0 auto;
      padding: 8px 20px;
      display: flex;
      align-items: center;
      gap: 20px;
    }
    .stat-item {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 12.5px;
      color: var(--text-secondary);
      white-space: nowrap;
    }
    .stat-label { color: var(--text-muted); font-size: 12px; }
    .stat-value { font-weight: 600; color: var(--text-primary); font-family: var(--mono); font-size: 12.5px; }
    .stat-change { font-size: 11.5px; font-weight: 500; }
    .stat-change.up { color: var(--green); }
    .stat-change.down { color: var(--red); }
    .stat-neutral { color: var(--text-muted); font-size: 12px; }
    .stats-divider {
      width: 1px; height: 16px;
      background: var(--border);
      flex-shrink: 0;
    }
    .fg-meter {
      display: inline-flex;
      align-items: center;
      gap: 5px;
    }
    .fg-badge {
      background: #f59e0b;
      color: #fff;
      font-size: 11px;
      font-weight: 700;
      padding: 2px 7px;
      border-radius: 10px;
    }

    /* ─── AI Alerts Bar ─────────────────────────────────────────────────── */
    .ai-bar {
      background: linear-gradient(135deg, #f0f4ff 0%, #f8f9ff 100%);
      border-bottom: 1px solid var(--border-light);
      padding: 10px 20px;
    }
    .ai-bar-inner {
      max-width: 1440px;
      margin: 0 auto;
      display: flex;
      align-items: center;
      gap: 12px;
      flex-wrap: wrap;
    }
    .ai-chip {
      display: flex;
      align-items: center;
      gap: 6px;
      background: #fff;
      border: 1px solid #dde4ff;
      border-radius: 20px;
      padding: 5px 12px;
      font-size: 12px;
      font-weight: 500;
      color: var(--brand-blue);
      cursor: pointer;
      transition: background 0.15s, border-color 0.15s, box-shadow 0.15s;
      white-space: nowrap;
    }
    .ai-chip:hover { background: #f0f4ff; border-color: var(--brand-blue); box-shadow: 0 2px 8px rgba(56,97,251,0.1); }
    .ai-label {
      font-size: 11.5px;
      font-weight: 700;
      color: var(--brand-blue);
      background: rgba(56,97,251,0.08);
      padding: 3px 8px;
      border-radius: 4px;
      white-space: nowrap;
      letter-spacing: 0.02em;
    }
    .ai-prompt {
      font-size: 13px;
      font-weight: 600;
      color: var(--text-primary);
      white-space: nowrap;
    }

    /* ─── Main Content ──────────────────────────────────────────────────── */
    .main-content {
      max-width: 1440px;
      margin: 0 auto;
      padding: 24px 20px 60px;
    }

    /* ─── Page Heading ──────────────────────────────────────────────────── */
    .page-heading {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      margin-bottom: 20px;
      gap: 20px;
      flex-wrap: wrap;
    }
    .page-title { font-size: 22px; font-weight: 700; color: var(--text-primary); }
    .page-subtitle { font-size: 13px; color: var(--text-muted); margin-top: 3px; }

    /* ─── Index Strip ────────────────────────────────────────────────────── */
    .index-strip {
      background: var(--bg-secondary);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 10px 16px;
      display: flex;
      align-items: center;
      gap: 20px;
      margin-bottom: 20px;
      overflow-x: auto;
    }
    .index-strip::-webkit-scrollbar { height: 0; }
    .index-name { font-size: 13px; font-weight: 600; color: var(--text-primary); white-space: nowrap; }
    .index-ticker { font-size: 11px; color: var(--text-muted); font-family: var(--mono); }
    .index-price { font-family: var(--mono); font-size: 14px; font-weight: 600; }
    .index-changes { display: flex; gap: 12px; align-items: center; }
    .idx-chg { font-family: var(--mono); font-size: 12px; font-weight: 500; }
    .idx-lbl { font-size: 11px; color: var(--text-muted); margin-right: 2px; }

    /* ─── Network + Category Tabs ───────────────────────────────────────── */
    .tabs-section {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      margin-bottom: 4px;
      flex-wrap: wrap;
    }
    .tab-group { display: flex; gap: 2px; }
    .tab-btn {
      padding: 7px 14px;
      border-radius: var(--radius-sm);
      font-size: 13px;
      font-weight: 500;
      color: var(--text-secondary);
      background: transparent;
      border: 1px solid transparent;
      transition: all 0.15s;
      white-space: nowrap;
    }
    .tab-btn:hover { background: var(--bg-tertiary); color: var(--text-primary); }
    .tab-btn.active {
      background: var(--brand-blue);
      color: #fff;
      border-color: var(--brand-blue);
      font-weight: 600;
    }
    .tab-btn.network.active {
      background: transparent;
      color: var(--brand-blue);
      border-color: var(--brand-blue);
    }

    /* ─── Table Controls ────────────────────────────────────────────────── */
    .table-controls {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      margin-bottom: 0;
      padding: 12px 0 0;
      flex-wrap: wrap;
    }
    .sort-tabs { display: flex; gap: 4px; align-items: center; }
    .sort-btn {
      padding: 6px 12px;
      border-radius: var(--radius-sm);
      font-size: 12.5px;
      font-weight: 500;
      color: var(--text-secondary);
      border: 1px solid var(--border);
      background: var(--bg);
      display: flex; align-items: center; gap: 4px;
      transition: all 0.15s;
    }
    .sort-btn:hover { border-color: var(--brand-blue); color: var(--brand-blue); }
    .sort-btn.active { background: var(--bg-secondary); font-weight: 600; color: var(--text-primary); }
    .ctrl-btn {
      padding: 6px 12px;
      border-radius: var(--radius-sm);
      font-size: 12.5px;
      font-weight: 500;
      color: var(--text-secondary);
      border: 1px solid var(--border);
      background: var(--bg);
      display: flex; align-items: center; gap: 5px;
      transition: all 0.15s;
    }
    .ctrl-btn:hover { border-color: var(--brand-blue); color: var(--brand-blue); }
    .ctrl-btn.open {
      background: var(--bg-secondary);
      border-color: var(--brand-blue);
      color: var(--brand-blue);
    }
    .ctrl-group { display: flex; gap: 6px; }

    /* ─── Dropdown Panels ───────────────────────────────────────────────── */
    .panel-wrapper { position: relative; display: inline-block; }
    .dropdown-panel {
      position: absolute;
      right: 0;
      top: calc(100% + 6px);
      background: var(--bg);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      box-shadow: var(--shadow-md);
      padding: 16px;
      z-index: 50;
      min-width: 220px;
      display: none;
    }
    .dropdown-panel.open { display: block; }
    .panel-title { font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-muted); margin-bottom: 10px; }
    .col-toggle-list { display: flex; flex-direction: column; gap: 6px; }
    .col-toggle {
      display: flex; align-items: center; justify-content: space-between;
      padding: 6px 8px;
      border-radius: var(--radius-sm);
      cursor: pointer;
      transition: background 0.15s;
    }
    .col-toggle:hover { background: var(--bg-secondary); }
    .col-toggle-label { font-size: 13px; font-weight: 500; color: var(--text-primary); }
    .col-toggle input[type="checkbox"] { accent-color: var(--brand-blue); width: 14px; height: 14px; cursor: pointer; }
    .filter-row { margin-bottom: 10px; }
    .filter-label { font-size: 11.5px; font-weight: 600; color: var(--text-muted); margin-bottom: 5px; text-transform: uppercase; letter-spacing: 0.05em; }
    .filter-select {
      width: 100%;
      padding: 7px 10px;
      border: 1px solid var(--border);
      border-radius: var(--radius-sm);
      font-size: 13px;
      font-family: var(--font);
      color: var(--text-primary);
      background: var(--bg);
      outline: none;
    }
    .filter-select:focus { border-color: var(--brand-blue); }

    /* ─── Table ─────────────────────────────────────────────────────────── */
    .table-container {
      width: 100%;
      overflow-x: auto;
      border: 1px solid var(--border);
      border-radius: var(--radius);
      margin-top: 8px;
    }
    table {
      width: 100%;
      border-collapse: collapse;
      font-size: 13.5px;
    }
    thead th {
      background: var(--bg-secondary);
      padding: 10px 12px;
      font-size: 11.5px;
      font-weight: 600;
      color: var(--text-muted);
      text-transform: uppercase;
      letter-spacing: 0.05em;
      white-space: nowrap;
      border-bottom: 1px solid var(--border);
      user-select: none;
    }
    thead th.sortable { cursor: pointer; }
    thead th.sortable:hover { color: var(--brand-blue); }
    thead th.num { text-align: right; }
    thead th.rank-col { text-align: center; width: 52px; }

    tbody tr {
      border-bottom: 1px solid var(--border-light);
      transition: background 0.1s;
    }
    tbody tr:last-child { border-bottom: none; }
    tbody tr:hover { background: var(--bg-secondary); }
    tbody tr.index-row { background: linear-gradient(90deg, #f0f4ff 0%, #f8f9ff 100%); }
    tbody tr.index-row:hover { background: linear-gradient(90deg, #e6ecff 0%, #f0f4ff 100%); }

    td {
      padding: 11px 12px;
      white-space: nowrap;
    }
    td.rank { text-align: center; font-family: var(--mono); font-size: 12.5px; color: var(--text-muted); font-weight: 500; }
    td.name-cell { min-width: 160px; }
    td.num { text-align: right; font-family: var(--mono); font-size: 13px; }
    td.pct { text-align: right; font-family: var(--mono); font-size: 12.5px; font-weight: 500; }
    td.pct.up { color: var(--green); }
    td.pct.down { color: var(--red); }

    .coin-name-wrap { display: flex; align-items: center; gap: 8px; }
    .coin-icon {
      width: 28px; height: 28px; border-radius: 50%;
      display: flex; align-items: center; justify-content: center;
      font-size: 11px; font-weight: 700; color: #fff;
      flex-shrink: 0;
    }
    .coin-name { font-weight: 600; font-size: 13.5px; color: var(--text-primary); }
    .coin-symbol { font-size: 11.5px; color: var(--text-muted); font-family: var(--mono); font-weight: 500; }
    .watchlist-star {
      color: var(--border);
      cursor: pointer;
      font-size: 14px;
      transition: color 0.15s;
      margin-right: 4px;
    }
    .watchlist-star:hover, .watchlist-star.starred { color: #f59e0b; }

    /* ─── Sparklines ─────────────────────────────────────────────────────── */
    .sparkline-cell { text-align: right; width: 80px; }
    .sparkline {
      display: inline-block;
      vertical-align: middle;
    }

    /* ─── Supply bar ─────────────────────────────────────────────────────── */
    .supply-cell { min-width: 140px; }
    .supply-bar-wrap { display: flex; align-items: center; gap: 6px; }
    .supply-bar-bg {
      width: 72px; height: 4px;
      background: var(--bg-tertiary);
      border-radius: 2px;
      overflow: hidden;
    }
    .supply-bar-fill { height: 100%; border-radius: 2px; background: var(--brand-blue); }

    /* ─── Pagination ─────────────────────────────────────────────────────── */
    .pagination-wrap {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 16px 12px;
      border-top: 1px solid var(--border-light);
      flex-wrap: wrap;
      gap: 12px;
    }
    .page-count-info { font-size: 12.5px; color: var(--text-muted); }
    .page-buttons { display: flex; align-items: center; gap: 3px; }
    .page-btn {
      width: 30px; height: 30px;
      border: 1px solid var(--border);
      border-radius: var(--radius-sm);
      font-size: 12.5px;
      font-weight: 500;
      color: var(--text-secondary);
      background: var(--bg);
      display: flex; align-items: center; justify-content: center;
      cursor: pointer;
      transition: all 0.15s;
    }
    .page-btn:hover { border-color: var(--brand-blue); color: var(--brand-blue); }
    .page-btn.active { background: var(--brand-blue); border-color: var(--brand-blue); color: #fff; font-weight: 600; }
    .page-btn.ellipsis { border: none; background: none; color: var(--text-muted); cursor: default; }
    .page-btn:hover.ellipsis { color: var(--text-muted); border: none; }
    .page-btn.prev-next { width: auto; padding: 0 10px; }

    /* ─── Market Summary ─────────────────────────────────────────────────── */
    .market-summary {
      background: var(--bg-secondary);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 20px 24px;
      margin-top: 28px;
    }
    .ms-title { font-size: 14px; font-weight: 700; color: var(--text-primary); margin-bottom: 10px; }
    .ms-text { font-size: 13.5px; color: var(--text-secondary); line-height: 1.7; }
    .ms-text strong { color: var(--text-primary); font-weight: 600; }
    .ms-expand {
      display: block;
      margin-top: 10px;
      font-size: 13px;
      font-weight: 600;
      color: var(--brand-blue);
      cursor: pointer;
      transition: opacity 0.15s;
    }
    .ms-expand:hover { opacity: 0.8; }
    .ms-extra { display: none; margin-top: 12px; }
    .ms-extra.open { display: block; }
    .ms-stats-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
      gap: 12px;
      margin-top: 14px;
    }
    .ms-stat-card {
      background: var(--bg);
      border: 1px solid var(--border);
      border-radius: var(--radius-sm);
      padding: 12px 14px;
    }
    .ms-stat-label { font-size: 11.5px; color: var(--text-muted); font-weight: 500; margin-bottom: 4px; text-transform: uppercase; letter-spacing: 0.04em; }
    .ms-stat-value { font-size: 15px; font-weight: 700; font-family: var(--mono); color: var(--text-primary); }
    .ms-stat-sub { font-size: 11.5px; color: var(--green); margin-top: 2px; font-weight: 500; }
    .ms-stat-sub.neg { color: var(--red); }

    /* ─── Info Content ───────────────────────────────────────────────────── */
    .info-section {
      margin-top: 40px;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 20px 32px;
    }
    @media (max-width: 768px) { .info-section { grid-template-columns: 1fr; } }
    .info-card h3 { font-size: 15px; font-weight: 700; color: var(--text-primary); margin-bottom: 8px; }
    .info-card p { font-size: 13.5px; color: var(--text-secondary); line-height: 1.7; }

    /* ─── Footer ─────────────────────────────────────────────────────────── */
    footer {
      background: var(--brand-navy);
      color: #a0aec0;
      padding: 44px 0 28px;
      margin-top: 60px;
    }
    .footer-inner {
      max-width: 1440px;
      margin: 0 auto;
      padding: 0 20px;
    }
    .footer-top {
      display: grid;
      grid-template-columns: 1.6fr repeat(4, 1fr);
      gap: 32px;
      margin-bottom: 36px;
    }
    @media (max-width: 900px) {
      .footer-top { grid-template-columns: 1fr 1fr; }
    }
    @media (max-width: 550px) {
      .footer-top { grid-template-columns: 1fr; }
    }
    .footer-brand .logo { color: #fff; margin-bottom: 10px; }
